// Ampliação baseada no resumo e nas duas páginas de revisão enviados em 27/10/2026.
let studyUnit='areas',exerciseSet='topic',lessonIndex=0,lessonStep=1;
let guideChecks=[];
try{const stored=JSON.parse(localStorage.getItem('orbita-roteiro-v2')||'[]');if(Array.isArray(stored))guideChecks=stored.filter(x=>Number.isInteger(x)&&x>=0&&x<5)}catch{}
const guideItems=['Revisar círculo, raio e comprimento','Distinguir perímetro de área','Resolver áreas e figuras compostas','Converter unidades de área','Fazer o simulado e revisar os erros'];
const studyTips={
 'Perímetro':'Perímetro mede todo o contorno. Some os lados: no retângulo, P = 2 × (comprimento + largura); no quadrado, P = 4 × lado. A unidade é m ou cm, sem o quadrado.',
 'Área do retângulo e do quadrado':'Área mede a superfície. No retângulo, A = comprimento × largura; no quadrado, A = lado × lado. Imagine quantos quadradinhos unitários cobrem a figura. Use m² ou cm².',
 'Área do triângulo':'A = (base × altura) ÷ 2. A altura faz um ângulo reto (90°) com a base; ela não é necessariamente um lado inclinado. Dois triângulos iguais podem compor um paralelogramo de mesma base e altura.',
 'Figuras compostas':'Divida a figura em partes conhecidas e some as áreas sem contar nenhuma região duas vezes. Se uma região é retirada, subtraia sua área da área total.',
 'Unidades de área':'Confira as unidades antes de calcular. Na sequência km² → hm² → dam² → m² → dm² → cm² → mm², cada passo para a direita multiplica por 100; para a esquerda, divide por 100. De m² para cm² são dois passos: × 10.000.',
 'Área e perímetro':'Área conta quadradinhos de superfície; perímetro mede a borda. Figuras com a mesma área podem ter perímetros diferentes. As unidades também mudam: área em cm² ou m²; perímetro em cm ou m.'
};
const sheetQuestions=[
 Q('01 · Um professor mostrou uma moeda, um anel e uma bola. Qual é a diferença entre círculo e circunferência?',['O círculo é apenas a linha do contorno.','A circunferência é a região interna.','O círculo inclui interior e contorno; a circunferência é somente o contorno.','Círculo e circunferência são tridimensionais.'],2,'A face da moeda representa um círculo: região interna e borda. O anel lembra a circunferência: apenas o contorno. A bola representa uma esfera, que é tridimensional.','As três formas'),
 Q('02 · Uma praça circular tem raio de 8 m. Uma faixa passa pelo centro e liga dois pontos opostos da borda. Quanto ela mede?',['4 m','8 m','12 m','16 m'],3,'A faixa passa pelo centro e liga duas bordas, portanto é um diâmetro. d = 2 × r = 2 × 8 = 16 m. Não confunda o raio com a distância de uma borda à outra.','Raio e diâmetro'),
 Q('03 · Uma roda de bicicleta tem raio de 30 cm. Qual é o comprimento aproximado da circunferência? Use π ≈ 3,14.',['94,2 cm','188,4 cm','282,6 cm','376,8 cm'],1,'Uma volta: C = 2 × 3,14 × 30 = 188,4 cm. O resultado 94,2 esquece o fator 2; 376,8 corresponde a duas voltas.','Comprimento'),
 Q('04 · Um atleta dá duas voltas em uma pista circular de raio 50 m. Qual distância ele percorre? Use π ≈ 3,14.',['157 m','314 m','628 m','1.256 m'],2,'Uma volta mede C = 2 × 3,14 × 50 = 314 m. Duas voltas: 2 × 314 = 628 m. Primeiro calcule uma volta, depois multiplique pelo número de voltas.','Comprimento'),
 Q('05 · Uma sala retangular mede 6 m de comprimento e 4 m de largura. Qual é a área do piso?',['10 m²','20 m²','24 m²','28 m²'],2,'Para cobrir o piso, calculamos área: A = 6 × 4 = 24 m². Somar 6 + 4 não mede a superfície; 2 × (6 + 4) = 20 m seria o perímetro, com outra unidade.','Área do retângulo e do quadrado'),
 Q('06 · Um terreno retangular mede 12 m por 5 m. Qual é a quantidade mínima de cerca para contorná-lo?',['17 m','24 m','34 m','60 m'],2,'Cerca percorre o contorno: P = 12 + 5 + 12 + 5 = 2 × (12 + 5) = 34 m. O produto 12 × 5 = 60 m² mede a área, não a cerca.','Perímetro'),
 Q('07 · Uma bandeira triangular tem base de 10 cm e altura de 6 cm. Qual é sua área?',['16 cm²','30 cm²','60 cm²','120 cm²'],1,'A = (base × altura) ÷ 2 = (10 × 6) ÷ 2 = 30 cm². A altura é perpendicular à base. O resultado 60 cm² esquece a divisão por 2.','Área do triângulo'),
 Q('08 · Uma quadra tem área de 200 m². Quanto isso representa em centímetros quadrados?',['2.000 cm²','20.000 cm²','200.000 cm²','2.000.000 cm²'],3,'1 m² = 100 cm × 100 cm = 10.000 cm². Portanto, 200 × 10.000 = 2.000.000 cm². São dois passos: m² → dm² → cm², cada um multiplicando por 100.','Unidades de área'),
 Q('09 · Um jardim retangular mede 10 m por 6 m. Há nele um canteiro quadrado de lado 2 m. Qual é a área restante?',['48 m²','52 m²','56 m²','60 m²'],2,'Jardim: 10 × 6 = 60 m². Canteiro: 2 × 2 = 4 m². Área restante: 60 − 4 = 56 m². Retire a área do canteiro, não seu perímetro.','Figuras compostas'),
 Q('10 · Dois desenhos ocupam, cada um, 12 quadradinhos de 1 cm². O que podemos afirmar?',['Têm necessariamente o mesmo perímetro.','Têm a mesma área, mesmo com formatos diferentes.','Têm necessariamente o mesmo número de lados.','São obrigatoriamente iguais.'],1,'Cada desenho ocupa 12 × 1 = 12 cm². A área é igual, mas o formato e o perímetro podem mudar. Por exemplo, retângulos 3 × 4 e 2 × 6 têm área 12 e perímetros 14 e 16.','Área e perímetro')
];
const extraPractice=[
 Q('Um quadrado tem lado de 5 cm. Quais são seu perímetro e sua área?',['P = 20 cm e A = 25 cm²','P = 25 cm e A = 20 cm²','P = 10 cm e A = 10 cm²'],0,'Perímetro: 4 × 5 = 20 cm. Área: 5 × 5 = 25 cm². O primeiro mede a borda; a segunda, a superfície.','Área do retângulo e do quadrado'),
 Q('Uma figura reúne, sem sobreposição, um retângulo de 4 m × 3 m e um quadrado de lado 2 m. Qual é a área total?',['14 m²','16 m²','20 m²'],1,'Calcule cada parte: 4 × 3 = 12 m² e 2 × 2 = 4 m². Como não se sobrepõem, some: 12 + 4 = 16 m².','Figuras compostas'),
 Q('20.000 cm² equivalem a quantos metros quadrados?',['2 m²','20 m²','200 m²'],0,'Para passar de cm² para m², divida por 10.000: 20.000 ÷ 10.000 = 2 m². A unidade ficou maior, então o número diminui.','Unidades de área'),
 Q('Em um triângulo, qual medida deve ser usada como altura?',['Sempre o maior lado','Um segmento perpendicular à base escolhida, até o vértice oposto','Qualquer lado inclinado'],1,'A altura forma 90° com a base (ou seu prolongamento) e chega ao vértice oposto. Um lado inclinado não pode ser usado como altura sem verificar essa condição.','Área do triângulo')
];
sheetQuestions.forEach(q=>{q.q=q.q.replace(/^\d{2} · /,'')});
const areaQuestions=[...sheetQuestions.slice(4),...extraPractice];
const questionBanks={
 circle:{practice:[...practice,...sheetQuestions.slice(0,4)],final:finalQuestions},
 areas:{practice:areaQuestions,final:areaQuestions},
 geral:[...finalQuestions,...areaQuestions]
};
const unitNames={circle:'Circunferência e esfera',areas:'Perímetro e áreas'};
questions=()=>mode==='final'&&exerciseSet==='geral'?questionBanks.geral:questionBanks[studyUnit][mode==='practice'?'practice':'final'];
const originalReset=reset;
reset=function(m){if(m==='final'&&stage!==3)exerciseSet='topic';originalReset(m)};
function unitTabs(){const general=stage===3&&exerciseSet==='geral';return `<div class="unit-tabs controls" aria-label="Blocos de estudo"><button class="chip ${studyUnit==='circle'&&!general?'selected':''}" data-unit="circle" aria-pressed="${studyUnit==='circle'&&!general}">◎ Circunferência e esfera</button><button class="chip ${studyUnit==='areas'&&!general?'selected':''}" data-unit="areas" aria-pressed="${studyUnit==='areas'&&!general}"><span>▱ Perímetro e áreas</span></button>${stage===0||stage===3?`<button class="chip ${general?'selected':''}" id="general-review" aria-pressed="${general}">✦ Revisão geral</button>`:''}</div>`}
function bindUnits(){document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{if(studyUnit!==b.dataset.unit||(stage===3&&exerciseSet==='geral')){studyUnit=b.dataset.unit;if(stage===2||stage===3){exerciseSet='topic';reset(stage===2?'practice':'final')}}render();$('#main').focus()});const generalButton=$('#general-review');if(generalButton)generalButton.onclick=()=>{if(stage!==3||exerciseSet!=='geral'){stage=3;exerciseSet='geral';reset('final')}navigate(3);$('#general-review').focus()};}
function guide(){return `<section class="panel guide"><span class="eyebrow">SEU ROTEIRO DE ESTUDO</span><h2>Uma ideia de cada vez</h2><p class="small">Siga a ordem e marque o que já estudou. As marcações ficam neste navegador, quando o armazenamento está disponível.</p><div class="guide-grid">${guideItems.map((s,i)=>`<label><input type="checkbox" data-guide="${i}" ${guideChecks.includes(i)?'checked':''}><span><b>0${i+1}</b> ${s}</span></label>`).join('')}</div><p class="small" id="guide-status" role="status">${guideChecks.length} de 5 passos marcados por você.</p><button class="text-button" id="clear-guide">Limpar marcações</button></section>`}
function bindGuide(){document.querySelectorAll('[data-guide]').forEach(el=>el.onchange=()=>{const i=+el.dataset.guide;guideChecks=guideChecks.filter(x=>x!==i);if(el.checked)guideChecks.push(i);saveGuide()});$('#clear-guide').onclick=()=>{guideChecks=[];document.querySelectorAll('[data-guide]').forEach(x=>x.checked=false);saveGuide()};}
function saveGuide(){try{localStorage.setItem('orbita-roteiro-v2',JSON.stringify(guideChecks))}catch{}$('#guide-status').textContent=`${guideChecks.length} de 5 passos marcados por você.`}
function svgWrap(label,body){return `<svg class="study-diagram" viewBox="0 0 360 220" role="img" aria-label="${label}">${body}</svg>`}
function rectangleDiagram(){return svgWrap('Retângulo de 6 por 4, dividido em 24 quadradinhos de 1 metro quadrado',`<rect x="60" y="20" width="240" height="160" fill="#ede6fc" stroke="#7153bd" stroke-width="4"/>${[1,2,3,4,5].map(i=>`<path d="M${60+i*40} 20v160" stroke="#baa7df"/>`).join('')}${[1,2,3].map(i=>`<path d="M60 ${20+i*40}h240" stroke="#baa7df"/>`).join('')}<text x="180" y="208" text-anchor="middle">6 m</text><text x="15" y="110">4 m</text>`)}
function triangleDiagram(){return svgWrap('Triângulo de base 10 cm e altura perpendicular de 6 cm, dentro de um retângulo',`<rect x="50" y="25" width="260" height="150" fill="#fbf5e8" stroke="#c6b9d6" stroke-dasharray="5 5"/><path d="M50 175L150 25L310 175Z" fill="#ffe0a1" stroke="#b4781b" stroke-width="3"/><path d="M150 25v150m0-14h14v14" fill="none" stroke="#7153bd" stroke-width="2" stroke-dasharray="4 3"/><text x="165" y="100">h = 6 cm</text><text x="180" y="205" text-anchor="middle">b = 10 cm</text>`)}
function gardenDiagram(){return svgWrap('Jardim de 10 por 6 metros com um canteiro quadrado de 2 por 2 metros retirado da área restante',`<rect x="55" y="20" width="250" height="150" fill="#d9f2e8" stroke="#308667" stroke-width="3"/><rect x="155" y="70" width="50" height="50" fill="#ffe2ac" stroke="#a87425" stroke-width="2"/><text x="180" y="60" text-anchor="middle">canteiro: 2 × 2 m</text><text x="180" y="199" text-anchor="middle">10 m</text><text x="12" y="100">6 m</text>`)}
function learn(){if(studyUnit==='circle'){originalLearn();$('.hero').insertAdjacentHTML('afterend',unitTabs()+guide());}else{
 $('#main').innerHTML=hero('NOVO CAPÍTULO · GEOMETRIA EM AÇÃO','Por fora, contorno.<br>Por dentro, área.','Aprenda a escolher a conta certa para cercar um terreno, cobrir um piso e comparar superfícies.')+unitTabs()+guide()+`<div class="cards concept-cards"><article class="card"><span class="tag">CONTORNAR</span><h3>Perímetro</h3><p>Imagine caminhar por toda a borda. Some os lados para descobrir o comprimento do caminho.</p><b>Unidades: cm, m, km</b></article><article class="card"><span class="tag">COBRIR</span><h3>Área</h3><p>Imagine preencher a figura com quadradinhos. Conte a superfície ocupada.</p><b>Unidades: cm², m², km²</b></article><article class="card"><span class="tag">DAR UMA VOLTA</span><h3>Circunferência</h3><p>Para um contorno circular, use C = 2 × π × r ou C = π × d.</p><b>Use o π do enunciado</b></article></div><div class="tip"><b>Pergunta-guia:</b> vou cercar ou cobrir? Cerca → perímetro. Piso → área. Volta em pista circular → comprimento da circunferência.</div><section class="panel"><h2>Retângulo e quadrado</h2><div class="lab">${rectangleDiagram()}<div><h3>Uma sala de 6 m por 4 m</h3><p>São 4 fileiras de 6 quadradinhos de 1 m²: 24 quadradinhos.</p><p class="formula">A = 6 × 4 = 24 m²</p><p>Já a borda mede 6 + 4 + 6 + 4 = <b>20 m</b>.</p></div></div><div class="formula-grid"><div><b>Retângulo</b><p>A = comprimento × largura<br>P = 2 × (comprimento + largura)</p></div><div><b>Quadrado</b><p>A = lado × lado<br>P = 4 × lado</p></div></div><p>Exemplo do resumo: terreno de 8 m por 5 m → P = 2 × (8 + 5) = <b>26 m de cerca</b>.</p></section><section class="panel"><h2>Triângulo: não esqueça a metade</h2><div class="lab">${triangleDiagram()}<div><p>A área do triângulo é metade do produto da base pela altura.</p><p class="formula">A = (b × h) ÷ 2</p><p>Base 10 cm e altura 6 cm: (10 × 6) ÷ 2 = <b>30 cm²</b>.</p><div class="tip">A altura faz <b>90° com a base</b>. Ela não é necessariamente um lado inclinado.</div></div></div></section><section class="panel"><h2>Figuras compostas: juntar ou retirar?</h2><div class="lab">${gardenDiagram()}<div><p><b>Juntar partes sem sobreposição:</b> calcule cada área e some.</p><p><b>Retirar uma região:</b> calcule a área total e subtraia a parte retirada.</p><p>Jardim: 10 × 6 = 60 m². Canteiro: 2 × 2 = 4 m².</p><p class="formula">60 − 4 = 56 m²</p></div></div><p class="small">Se as partes se sobrepõem, não conte a região comum duas vezes.</p></section><section class="panel"><h2>Unidades de área: cada passo vale 100</h2><p>Em medidas de comprimento, cada passo vale 10. Em área, são duas dimensões: 10 × 10 = <b>100</b>.</p><div class="unit-ladder" aria-label="Sequência de unidades quadradas">km² → hm² → dam² → <b>m²</b> → dm² → <b>cm²</b> → mm²</div><p>Para a direita: multiplique por 100 a cada passo. Para a esquerda: divida por 100.</p><div class="tip"><b>m² → cm² são DOIS passos.</b> 1 m² = 100 cm × 100 cm = <b>10.000 cm²</b>.</div><p>3 m² = 30.000 cm² · 20.000 cm² = 2 m²</p><p><b>Antes de calcular:</b> coloque as medidas na mesma unidade. Se a base estiver em metros e a altura em centímetros, converta uma delas primeiro.</p></section><section class="panel"><h2>A mesma área pode ter outra borda</h2><p>Dois desenhos com 12 quadradinhos de 1 cm² têm área de <b>12 cm²</b>. Eles podem ter formatos e perímetros diferentes.</p><div class="formula-grid"><div><b>Retângulo 3 cm × 4 cm</b><p>A = 12 cm²<br>P = 2 × (3 + 4) = 14 cm</p></div><div><b>Retângulo 2 cm × 6 cm</b><p>A = 12 cm²<br>P = 2 × (2 + 6) = 16 cm</p></div></div></section><div class="end-row"><span class="small">Um passo de cada vez. Você está aprendendo!</span><button class="primary" id="new-examples">Ver exemplos passo a passo →</button></div>`;
 $('#new-examples').onclick=()=>navigate(1);
 }bindUnits();bindGuide();}
const newLessons=[
 {title:'A roda e as duas voltas',topic:'Comprimento',steps:['Na roda de raio 30 cm, queremos medir uma volta no contorno.','Use C = 2 × π × r. Com π ≈ 3,14: C = 2 × 3,14 × 30.','O comprimento aproximado da roda é 188,4 cm.','Na pista de raio 50 m: uma volta = 2 × 3,14 × 50 = 314 m. Duas voltas = 2 × 314 = 628 m.'],answer:'Roda: 188,4 cm · Atleta: 628 m'},
 {title:'Piso ou cerca?',topic:'Área e perímetro',steps:['A sala de 6 m por 4 m precisa de piso: vamos cobrir a superfície. Use área.','A = 6 × 4 = 24 m². A unidade é quadrada.','O terreno de 12 m por 5 m precisa de cerca: vamos percorrer a borda. Use perímetro.','P = 12 + 5 + 12 + 5 = 2 × (12 + 5) = 34 m. A unidade é de comprimento.'],answer:'Piso: 24 m² · Cerca: 34 m'},
 {title:'A bandeira triangular',topic:'Área do triângulo',steps:['Identifique base de 10 cm e altura perpendicular de 6 cm.','Multiplique: base × altura = 10 × 6 = 60.','Divida por 2: 60 ÷ 2 = 30.','Escreva a unidade de área: 30 cm². O lado inclinado não substitui a altura.'],answer:'Área da bandeira: 30 cm²'},
 {title:'O jardim com canteiro',topic:'Figuras compostas',steps:['Calcule toda a área do jardim: 10 × 6 = 60 m².','O canteiro é quadrado, com lado 2 m: 2 × 2 = 4 m².','A questão pede a região restante. Subtraia o canteiro: 60 − 4.','Restam 56 m². Não subtraia o lado de 2 m nem o perímetro de 8 m.'],answer:'Área restante: 56 m²'},
 {title:'A quadra em centímetros quadrados',topic:'Unidades de área',steps:['Queremos converter 200 m² para cm².','De m² para dm², multiplique por 100. De dm² para cm², multiplique de novo por 100.','O fator total é 100 × 100 = 10.000. Calcule 200 × 10.000.','Resultado: 2.000.000 cm². Uma unidade menor exige um número maior para a mesma área.'],answer:'200 m² = 2.000.000 cm²'},
 {title:'Juntar partes e medir um quadrado',topic:'Figuras compostas',steps:['Em um quadrado de lado 5 cm, o perímetro é 4 × 5 = 20 cm e a área é 5 × 5 = 25 cm².','Para uma figura composta, separe partes conhecidas sem sobreposição.','Exemplo complementar: retângulo de 4 m × 3 m unido a um quadrado de lado 2 m. As áreas são 12 m² e 4 m².','Some: 12 + 4 = 16 m². Esse procedimento vale quando as regiões não se sobrepõem.'],answer:'Some áreas das partes; mantenha a unidade quadrada.'}
];
function understand(){if(studyUnit==='circle'){originalUnderstand();$('.hero').insertAdjacentHTML('afterend',unitTabs());bindUnits();return}
 const e=newLessons[lessonIndex];$('#main').innerHTML=hero('ENTENDER · PASSO A PASSO','Primeiro a ideia.<br>Depois a conta.','Escolha um exemplo e revele uma etapa de cada vez. Tente antecipar o próximo passo.')+unitTabs()+`<section class="panel"><label for="lesson-select"><b>Escolha o exemplo</b></label><select id="lesson-select" class="wide-select">${newLessons.map((x,i)=>`<option value="${i}" ${i===lessonIndex?'selected':''}>${i+1}. ${x.title}</option>`).join('')}</select><h2>${e.title}</h2>${lessonIndex===2?triangleDiagram():lessonIndex===3?gardenDiagram():''}<ol class="steps" aria-live="polite">${e.steps.slice(0,lessonStep).map(s=>`<li>${s}</li>`).join('')}</ol>${lessonStep===e.steps.length?`<div class="tip"><b>${e.answer}</b></div>`:''}<div class="actions"><button class="primary" id="reveal-step" ${lessonStep===e.steps.length?'disabled':''}>Revelar próximo passo</button><button class="secondary" id="reset-step">Recomeçar exemplo</button><span class="small">${lessonStep} de ${e.steps.length} passos</span></div></section><section class="panel"><h2>Laboratório: cobrir e contornar</h2><p>Altere os lados de um retângulo. Cada quadradinho representa 1 m².</p><div class="lab"><div id="area-drawing"></div><div><label for="area-length">Comprimento: <b id="length-label"></b> m</label><input class="range" id="area-length" type="range" min="1" max="12" value="6"><label for="area-width">Largura: <b id="width-label"></b> m</label><input class="range" id="area-width" type="range" min="1" max="8" value="4"><div id="area-values" aria-live="polite"></div></div></div><div class="tip">Experimente 3 × 4 e depois 6 × 2: a área permanece 12 m², mas o perímetro muda.</div></section><section class="panel"><h2>Oficina de conversão</h2><label for="convert-value">Medida da área</label><input type="number" id="convert-value" value="200" min="0" step="any"><label for="convert-direction">Converter</label><select id="convert-direction"><option value="10000">m² para cm²</option><option value="0.0001">cm² para m²</option></select><p id="convert-answer" class="formula" aria-live="polite"></p><p class="small">O tamanho da região não muda; mudam a unidade e o número que a representa.</p></section><div class="end-row"><button class="text-button" id="back-new">← Revisar conceitos</button><button class="primary" id="practice-new">Praticar perímetro e áreas →</button></div>`;bindUnits();$('#lesson-select').onchange=e=>{lessonIndex=+e.target.value;lessonStep=1;understand();$('#lesson-select').focus()};$('#reveal-step').onclick=()=>{lessonStep=Math.min(lessonStep+1,e.steps.length);understand();$('#reset-step').focus()};$('#reset-step').onclick=()=>{lessonStep=1;understand();$('#reveal-step').focus()};$('#area-length').oninput=areaLab;$('#area-width').oninput=areaLab;areaLab();$('#convert-value').oninput=convertArea;$('#convert-direction').onchange=convertArea;convertArea();$('#back-new').onclick=()=>navigate(0);$('#practice-new').onclick=()=>{reset('practice');navigate(2)};}
function areaLab(){const l=+$('#area-length').value,w=+$('#area-width').value;$('#length-label').textContent=l;$('#width-label').textContent=w;$('#area-values').innerHTML=`<p><b>Área:</b> ${l} × ${w} = <strong>${l*w} m²</strong></p><p><b>Perímetro:</b> 2 × (${l} + ${w}) = <strong>${2*(l+w)} m</strong></p>`;$('#area-drawing').innerHTML=svgWrap(`Retângulo ${l} por ${w} metros: área ${l*w} metros quadrados e perímetro ${2*(l+w)} metros`,Array.from({length:l*w},(_,i)=>`<rect x="${30+(i%l)*24}" y="${12+Math.floor(i/l)*24}" width="24" height="24" fill="#ece5fa" stroke="#ad96d2"/>`).join('')+`<rect x="30" y="12" width="${l*24}" height="${w*24}" fill="none" stroke="#5135a6" stroke-width="3"/>`)}
function convertArea(){const raw=$('#convert-value').value,n=Number(raw),factor=+$('#convert-direction').value;$('#convert-answer').textContent=raw.trim()===''||!Number.isFinite(n)||n<0?'Digite uma área maior ou igual a zero.':`${fmt(n)} ${factor===10000?'m² × 10.000':'cm² ÷ 10.000'} = ${new Intl.NumberFormat('pt-BR',{maximumFractionDigits:10}).format(n*factor)} ${factor===10000?'cm²':'m²'}`}
function quiz(){originalQuiz();if(cursor>=questions().length)return;
 const general=mode==='final'&&exerciseSet==='geral';
 $('.hero h1').textContent=mode==='practice'?`Vamos praticar ${studyUnit==='circle'?'circunferência?':'perímetro e áreas?'}`:general?'Seu desafio geral.':'Seu desafio de hoje.';
 $('.hero p').textContent=general?'Uma revisão com os dois conteúdos. Use o que aprendeu e confira seu raciocínio.':`${unitNames[studyUnit]} · ${questions().length} questões para avançar no seu ritmo.`;
 $('.hero').insertAdjacentHTML('afterend',unitTabs()+(mode==='practice'?`<section class="quiz-selector"><b>Treino de ${unitNames[studyUnit].toLowerCase()}</b><p>${questions().length} questões sobre este conteúdo.</p><p class="small">Você pode consultar a explicação antes de responder. Trocar de conteúdo inicia um novo treino.</p></section>`:''));
 bindUnits();
 $('#review-before').onclick=()=>{const q=questions()[cursor],tip=studyTips[q.topic]||basics;openDialog(`<h2>Revisar: ${q.topic}</h2><p>${tip}</p><div class="tip"><b>Roteiro:</b> o que a questão pede? Quais são as medidas? Estão na mesma unidade? Escolha a fórmula, substitua os valores e confira a unidade da resposta.</div>${q.topic==='Comprimento'?'<p>Primeiro calcule uma volta; depois multiplique pelo número de voltas. Confira o valor de π indicado no enunciado.</p>':''}<p class="small">Feche para voltar à questão. Sua resposta ainda não foi confirmada.</p>`)};
}
function result(){originalResult();$('.result .pill').textContent=(mode==='final'&&exerciseSet==='geral'?'Revisão geral':unitNames[studyUnit])+' · '+(mode==='final'?'Desafio concluído':'Prática concluída');const qs=questions(),weak=[...new Set(qs.filter((q,i)=>!answers[i].correct).map(q=>q.topic))];$('#answer-review').insertAdjacentHTML('afterbegin',`<div class="tip"><b>Seu próximo passo:</b> ${weak.length?'revise os temas abaixo, leia a explicação de cada erro e refaça a etapa.':'explique com suas palavras por que cada resposta está correta. Depois, experimente o outro desafio.'}</div>${weak.map(t=>`<details><summary>Revisar ${t}</summary><p>${studyTips[t]||basics}</p></details>`).join('')}`);}
function showMaterial(page=1){const originals=Array.from({length:8},(_,i)=>({label:`PDF ${i+1} · Livro ${68+i}`,file:`pagina-0${i+1}.png`})),all=[...originals,{label:'Resumo novo · página 1',file:'resumo-1.jpg'},{label:'Resumo novo · página 2',file:'resumo-2.jpg'},{label:'Revisão · questões 1 a 4',file:'revisao-1.jpg'},{label:'Revisão · questões 5 a 10',file:'revisao-2.jpg'}];const selectedPage=all[page-1];openDialog(`<h2>Materiais da sua jornada</h2><p>PDF original, páginas 1–8, e os quatro novos anexos: resumo e exercícios de revisão.</p><label for="page-select">Escolha o material </label><select id="page-select" class="wide-select">${all.map((x,i)=>`<option value="${i+1}" ${page===i+1?'selected':''}>${x.label}</option>`).join('')}</select><p class="small">As fotos são referências. O conteúdo está transcrito e explicado nas etapas de estudo.</p><img class="page-image" src="material/${selectedPage.file}" alt="${selectedPage.label}">`);$('#page-select').onchange=e=>showMaterial(+e.target.value)}
render();
